import * as React from "react"
import { cva, type VariantProps } from "class-variance-authority"

import { cn } from "@/lib/utils"
import {
  flowToneStyle,
  type FlowToneName,
} from "@/registry/lib/flow-tone"
import "./timeline.css"

type TimelineStatus = "done" | "current" | "upcoming"
type TimelineOrientation = "vertical" | "horizontal"
type TimelineAlign = "start" | "alternate"

function Timeline({
  className,
  orientation = "vertical",
  align = "start",
  ...props
}: React.ComponentProps<"ol"> & {
  orientation?: TimelineOrientation
  /** 仅竖向时间线在宽屏交替排列。 */
  align?: TimelineAlign
}) {
  return (
    <ol
      data-slot="timeline"
      data-orientation={orientation}
      data-align={align}
      className={cn("isolate m-0 w-full list-none p-0", className)}
      {...props}
    />
  )
}

function TimelineItem({
  className,
  status = "done",
  time,
  children,
  ...props
}: React.ComponentProps<"li"> & {
  status?: TimelineStatus
  /** 左侧编号栏；建议传入 TimelineTime。 */
  time?: React.ReactNode
}) {
  return (
    <li
      data-slot="timeline-item"
      data-status={status}
      data-time={time ? "column" : undefined}
      aria-current={status === "current" ? "step" : undefined}
      className={cn("group/timeline-item relative min-w-0", className)}
      {...props}
    >
      {time ? <div data-slot="timeline-item-time">{time}</div> : null}
      {children}
    </li>
  )
}

const timelineMarkerVariants = cva(
  "relative z-10 flex size-8 shrink-0 items-center justify-center self-start rounded-full border border-edge bg-background font-mono text-xs text-(--flow-tone) [&_svg]:size-3.5",
  {
    variants: {
      status: {
        done: "",
        current: "ring-4 ring-(--flow-tone)/10 motion-safe:animate-pulse",
        upcoming: "border-dashed text-muted-foreground",
      },
    },
    defaultVariants: { status: "done" },
  },
)

function TimelineMarker({
  className,
  tone = "primary",
  status,
  style,
  children,
  label,
  ...props
}: React.ComponentProps<"span"> &
  VariantProps<typeof timelineMarkerVariants> & {
    tone?: FlowToneName
    /** 有语义的标记请提供文字说明。 */
    label?: string
  }) {
  return (
    <span
      data-slot="timeline-marker"
      data-status={status ?? undefined}
      role={label ? "img" : undefined}
      aria-label={label}
      aria-hidden={label ? undefined : true}
      className={cn(timelineMarkerVariants({ status }), className)}
      style={{ ...flowToneStyle(tone), ...style }}
      {...props}
    >
      {children ?? (
        <span
          data-slot="timeline-dot"
          className="size-2 rounded-full bg-current"
        />
      )}
    </span>
  )
}

function TimelineConnector({
  className,
  ...props
}: React.ComponentProps<"span">) {
  return (
    <span
      data-slot="timeline-connector"
      aria-hidden="true"
      className={cn("pointer-events-none border-edge", className)}
      {...props}
    />
  )
}

function TimelineContent({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="timeline-content"
      className={cn("min-w-0 pt-1 pb-8", className)}
      {...props}
    />
  )
}

function TimelineTitle({ className, ...props }: React.ComponentProps<"h3">) {
  return (
    <h3
      data-slot="timeline-title"
      className={cn(
        "m-0 text-sm leading-6 font-medium tracking-tight",
        className,
      )}
      {...props}
    />
  )
}

function TimelineTime({ className, ...props }: React.ComponentProps<"time">) {
  return (
    <time
      data-slot="timeline-time"
      className={cn(
        "shrink-0 font-mono text-xs leading-6 text-muted-foreground tabular-nums",
        className,
      )}
      {...props}
    />
  )
}

function TimelineDescription({
  className,
  ...props
}: React.ComponentProps<"p">) {
  return (
    <p
      data-slot="timeline-description"
      className={cn(
        "mt-1 mb-0 text-[13px] leading-7 text-muted-foreground",
        className,
      )}
      {...props}
    />
  )
}

function TimelineAttachment({
  className,
  ...props
}: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="timeline-attachment"
      className={cn(
        "mt-3 flex flex-wrap items-center gap-2 text-xs",
        className,
      )}
      {...props}
    />
  )
}

export {
  Timeline,
  TimelineItem,
  TimelineMarker,
  TimelineConnector,
  TimelineContent,
  TimelineTitle,
  TimelineTime,
  TimelineDescription,
  TimelineAttachment,
  timelineMarkerVariants,
}
export type { TimelineStatus, TimelineOrientation, TimelineAlign }

[data-slot="timeline-item"] {
  display: grid;
  grid-template-columns: 2rem minmax(0, 1fr);
  column-gap: 1rem;
  animation: timeline-enter 250ms ease-out both;
}
[data-slot="timeline-marker"] {
  grid-column: 1;
  grid-row: 1;
}
[data-slot="timeline-content"] {
  grid-column: 2;
  grid-row: 1;
}
[data-slot="timeline-item-time"] {
  padding-top: 0.25rem;
  grid-column: 1;
  grid-row: 1;
}
[data-slot="timeline-item"][data-time="column"] {
  grid-template-columns: 3.5rem 2rem minmax(0, 1fr);
}
[data-time="column"] > [data-slot="timeline-marker"] {
  grid-column: 2;
}
[data-time="column"] > [data-slot="timeline-content"] {
  grid-column: 3;
}
[data-slot="timeline-connector"] {
  position: absolute;
  left: 1rem;
  top: 2rem;
  bottom: 0;
  border-left-width: 1px;
}
[data-time="column"] > [data-slot="timeline-connector"] {
  left: 5.5rem;
}
[data-slot="timeline-item"]:last-child > [data-slot="timeline-connector"] {
  display: none;
}
[data-slot="timeline-item"]:last-child > [data-slot="timeline-content"] {
  padding-bottom: 0;
}
[data-slot="timeline-item"][data-status="current"]
  > [data-slot="timeline-connector"],
[data-slot="timeline-item"][data-status="upcoming"]
  > [data-slot="timeline-connector"] {
  border-style: dashed;
}
[data-slot="timeline-item"][data-status="current"]
  > [data-slot="timeline-marker"]:not([data-status]) {
  outline: 4px solid color-mix(in oklch, var(--flow-tone) 12%, transparent);
}
[data-slot="timeline-item"][data-status="upcoming"]
  > [data-slot="timeline-marker"]:not([data-status]) {
  border-style: dashed;
  color: var(--muted-foreground);
}
@media (min-width: 640px) {
  [data-slot="timeline"][data-orientation="horizontal"] {
    display: flex;
  }
  [data-orientation="horizontal"] > [data-slot="timeline-item"] {
    flex: 1;
    display: flex;
    flex-direction: column;
    gap: 1rem;
  }
  [data-orientation="horizontal"]
    > [data-slot="timeline-item"]
    > [data-slot="timeline-content"] {
    padding: 0 1rem 0 0;
  }
  [data-orientation="horizontal"]
    > [data-slot="timeline-item"]
    > [data-slot="timeline-connector"] {
    top: 1rem;
    left: 2rem;
    right: 0;
    bottom: auto;
    border-left-width: 0;
    border-top-width: 1px;
  }
  [data-orientation="vertical"][data-align="alternate"]
    > [data-slot="timeline-item"] {
    grid-template-columns: minmax(0, 1fr) 2rem minmax(0, 1fr);
  }
  [data-orientation="vertical"][data-align="alternate"]
    > [data-slot="timeline-item"]
    > [data-slot="timeline-marker"] {
    grid-column: 2;
  }
  [data-orientation="vertical"][data-align="alternate"]
    > [data-slot="timeline-item"]
    > [data-slot="timeline-content"] {
    grid-column: 3;
  }
  [data-orientation="vertical"][data-align="alternate"]
    > [data-slot="timeline-item"]:nth-child(even)
    > [data-slot="timeline-content"] {
    grid-column: 1;
    text-align: right;
  }
  [data-orientation="vertical"][data-align="alternate"]
    > [data-slot="timeline-item"]
    > [data-slot="timeline-connector"] {
    left: 50%;
  }
  [data-orientation="vertical"][data-align="alternate"]
    > [data-slot="timeline-item"]
    > [data-slot="timeline-item-time"] {
    grid-column: 1;
    text-align: right;
  }
  [data-orientation="vertical"][data-align="alternate"]
    > [data-slot="timeline-item"]:nth-child(even)
    > [data-slot="timeline-item-time"] {
    grid-column: 3;
    text-align: left;
  }
}
@keyframes timeline-enter {
  from {
    transform: translateY(6px);
  }
  to {
    transform: translateY(0);
  }
}
@media (prefers-reduced-motion: reduce) {
  [data-slot="timeline-item"] {
    animation: none;
  }
}
